(* [comment removed for export] *)
Definition AGLOBALS : list (Z * Z * Z * Z * Z) := [
  (0x20e00, 8, 32, 0x147ac, 0x20e20);
  (0x20ea0, 128, 160, 0x175bb, 0x20f60);
  (0x20f40, 8, 32, 0x147ac, 0x20f60);
  (0x20fe0, 36, 96, 0x1c017, 0x20f99);
  (0x21040, 13, 32, 0x1e795, 0x20f99);
  (0x21060, 1, 32, 0x204ea, 0x20f99);
