Definition mdtor_pre (m : mem) : Prop :=
     mdtor_rt m
  /\ rw_cells bsegs m 0xb2dc0 [C8 (Z_to_bv 64 0xb69f0); C8 (Z_to_bv 64 0xb6c30)]     (* [comment removed for export] *)
  /\ rw_cells bsegs m 0xb6c40 [C8 (Z_to_bv 64 1)]                                     (* [comment removed for export] *)
  /\ rw_cells bsegs m 0xb7bb0 [C8 (Z_to_bv 64 0)]                                     (* [comment removed for export] *)
  /\ gdescs m 0xb69f0 AGLOBALS                                                        (* [comment removed for export] *)
  /\ (exists j, rw_cells bsegs m 0x7fffc1c0 [CB 144 j])                               (* [comment removed for export] *)
  /\ (exists j, rw_cells bsegs m 0x8000ed3e [CB 72 j]).                              (* [comment removed for export] *)

Lemma mdtor_pre_frame : forall sp m m',
  mdtor_pre m -> KHIGH <= sp - 48 - MDTOR_DEPTH -> munch (AEXIT_W1 sp) m m' -> wmono bsegs m m' -> mdtor_pre m'.
Proof.
  intros sp m m' P KH MU WM. unfold KHIGH, MDTOR_DEPTH in KH.
  unfold mdtor_pre in *.
  destruct P as (RT & G1 & G2 & G3 & GD & [j1 S1] & [j2 S2]).
  assert (RT' : mdtor_rt m').
  { eapply mdtor_rt_frame; [exact RT | exact MU | exact WM | ]. unfold AEXIT_W1, MDTOR_DEPTH.
    repeat (apply Forall_cons; [cbn; lia|]). apply Forall_nil. }
  refine (conj RT' _).
  split; [| split; [| split; [| split; [| split]]]].
  - eapply rw_cells_transport; [exact G1 | exact MU | exact WM | unfold AEXIT_W1, MDTOR_DEPTH; cbn; lia].
  - eapply rw_cells_transport; [exact G2 | exact MU | exact WM | unfold AEXIT_W1, MDTOR_DEPTH; cbn; lia].
  - eapply rw_cells_transport; [exact G3 | exact MU | exact WM | unfold AEXIT_W1, MDTOR_DEPTH; cbn; lia].
  - eapply gdescs_transport; [exact GD | exact MU | exact WM |]. rewrite AGLOBALS_length.
    intros A n0 H1 H2 H3. unfold AEXIT_W1, MDTOR_DEPTH; cbn; lia.
  - exists j1. eapply rw_cells_transport; [exact S1 | exact MU | exact WM | unfold AEXIT_W1, MDTOR_DEPTH; cbn; lia].
  - exists j2. eapply rw_cells_transport; [exact S2 | exact MU | exact WM | unfold AEXIT_W1, MDTOR_DEPTH; cbn; lia].
Qed.

