  0x10000 <= d -> d + 64 * Z.of_nat (length G) <= 0x60f000 -> 0x7fffa000 <= lo -> hi <= 0x800cd000 -> 0 <= spv < 2^64 ->
  rng_aimg RNG -> rng RNG lo (hi - lo) ->
